        if m: add(int(m.group(1)), m.group(3), m.group(2), m.group(4).strip(), 'c1')
for ln in open(D+'sort-c2.md'):
    m=re.match(r'- \*\*(\d+)\. (.*?)\*\* (S, stale|S|L|A|C|Unsettled)[.,] ?(.*)$', ln.rstrip('\n'))
